import pytest
import requests

BASE_URL = "http://api.example.com"  # Base URL for the API
ENDPOINT = "/store/order/{orderId}"


@pytest.mark.parametrize(
    "order_id, expected_status, expected_response_schema",
    [
        (1, 200, {"id": int, "petId": int, "quantity": int, "shipDate": str, "status": str, "complete": bool}),
        (6, 400, None),  # Invalid ID
        (999, 404, None),  # Order not found
    ],
)
def test_get_order_by_id(api_client, order_id, expected_status, expected_response_schema):
    """
    Test fetching an order by ID.

    Parameters:
    - `order_id`: ID of the order to fetch.
    - `expected_status`: Expected HTTP status code.
    - `expected_response_schema`: Expected schema of the response body for valid responses.
    """
    response = api_client.get(ENDPOINT.format(orderId=order_id))
    assert response.status_code == expected_status, f"Unexpected status code: {response.status_code}"

    if expected_status == 200:
        response_json = response.json()
        for key, value_type in expected_response_schema.items():
            assert key in response_json, f"Expected key `{key}` missing in response."
            assert isinstance(response_json[key], value_type), f"Key `{key}` has incorrect type."

    elif expected_status in (400, 404):
        # No specific schema for error responses in spec, just assert the status code is proper
        assert len(response.text) > 0, "Error response should contain a message."


def test_get_order_by_invalid_id_format(api_client):
    """
    Test fetching an order with an invalid `order_id` format (e.g., string instead of integer).
    """
    invalid_id = "invalid_id"

